import java.util.*;class WordDistance{Map<String,List<Integer>>m=new HashMap<>();public WordDistance(String[]w){for(int i=0;i<w.length;i++)m.computeIfAbsent(w[i],k->new ArrayList<>()).add(i);}public int shortest(String a,String b){List<Integer>x=m.get(a),y=m.get(b);int i=0,j=0,r=Integer.MAX_VALUE;while(i<x.size()&&j<y.size()){r=Math.min(r,Math.abs(x.get(i)-y.get(j)));if(x.get(i)<y.get(j))i++;else j++;}return r;}}
